html:
{#- Report View Table (ADR-019): any table, printed with no template work.
  data = {
    "columns": [{"label": "Item", "fieldname": "item", "fieldtype": "Data"},
                {"label": "Amount", "fieldname": "amount", "fieldtype": "Currency", "options": "SAR"}],
    "rows": [{"item": "A", "amount": 10}, ["B", 20]],     rows as objects or as lists
    "totals": true,                                       or {"amount": 30}: the totals as given
    "subtitle": "…", "note": "…"                          optional, plain text
  }
  report_view.print_table({title, columns, rows, totals}) sends exactly this. -#}
{%- set cols = data.columns or [] if data is mapping else [] -%}
{%- set numeric = ["Int", "Float", "Currency", "Percent"] -%}
{%- set summed = ["Int", "Float", "Currency"] -%}
<div class="rvt-print">
{%- if data.subtitle %}<p class="rvt-sub">{{ data.subtitle }}</p>{% endif %}
{%- if not cols %}<p class="rvt-empty">{{ _("No columns to print") }}</p>{% else %}
<table class="rvt">
<thead><tr>
{%- for c in cols %}<th class="{{ 'num' if c.fieldtype in numeric else '' }}"{% if c.width %} style="width:{{ c.width|int }}px"{% endif %}>{{ _(c.label or c.fieldname) }}</th>{% endfor -%}
</tr></thead>
<tbody>
{%- for row in rows %}<tr>
{%- for c in cols %}{% set v = row[c.fieldname] if row is mapping else (row[loop.index0] if loop.index0 < row|length else none) %}<td class="{{ 'num' if c.fieldtype in numeric else '' }}">{{ frappe.format(v, c) if v is not none else "" }}</td>{% endfor -%}
</tr>{% else %}<tr><td class="rvt-none" colspan="{{ cols|length }}">{{ _("No rows") }}</td></tr>{% endfor -%}
</tbody>
{%- if data.totals and rows %}
<tfoot><tr>
{%- for c in cols %}{% set ci = loop.index0 %}
{%- if data.totals is mapping %}{% set t = data.totals[c.fieldname] %}
{%- elif c.fieldtype in summed %}{% set ns = namespace(t=0) %}{% for r in rows %}{% set ns.t = ns.t + frappe.utils.flt(r[c.fieldname] if r is mapping else (r[ci] if ci < r|length else 0)) %}{% endfor %}{% set t = ns.t %}
{%- else %}{% set t = none %}{% endif %}
<td class="{{ 'num' if c.fieldtype in numeric else '' }}">{% if t is not none %}{{ frappe.format(t, c) }}{% elif loop.first %}{{ _("Total") }}{% endif %}</td>
{%- endfor -%}
</tr></tfoot>
{%- endif %}
</table>
{%- endif %}
{%- if data.note %}<p class="rvt-note">{{ data.note }}</p>{% endif %}
</div>

css:
/* the colours of the paper (Report View's page palette), currentColor where a page has none */
.rvt-print{font-size:inherit;color:var(--pp-tx,currentColor)}
.rvt-sub{margin:0 0 3mm;color:var(--pp-tx-2,currentColor)}
.rvt-note{margin:3mm 0 0;font-size:.92em;color:var(--pp-tx-3,currentColor)}
.rvt-empty{margin:0}
table.rvt{width:100%;border-collapse:collapse;border-spacing:0;font-size:inherit}
.rvt th,.rvt td{padding:1.2mm .55em;text-align:start;vertical-align:top;overflow-wrap:anywhere}
.rvt thead th{font-weight:700;font-size:.92em;background:var(--pp-head,transparent);border-top:1.2px solid var(--pp-tx,currentColor);border-bottom:1px solid var(--pp-tx,currentColor);vertical-align:bottom}
.rvt tbody td{border-bottom:.5px solid var(--pp-line,currentColor)}
.rvt tbody tr:nth-child(even) > td{background:var(--pp-zebra,transparent)}
.rvt .num{text-align:end;font-variant-numeric:tabular-nums;white-space:nowrap}
.rvt tfoot td{font-weight:700;border-top:1.2px solid var(--pp-tx,currentColor);border-bottom:3px double var(--pp-tx,currentColor);background:var(--pp-head,transparent)}
.rvt td.rvt-none{text-align:center;color:var(--pp-tx-3,currentColor)}
